using CoffeeControl.Api; using Microsoft.EntityFrameworkCore; using Serilog; using Telegram.Bot; using Telegram.Bot.Types; using Telegram.Bot.Types.ReplyMarkups;
var builder=WebApplication.CreateBuilder(args); builder.Host.UseSerilog((ctx,log)=>log.ReadFrom.Configuration(ctx.Configuration).WriteTo.Console()); var cs=Environment.GetEnvironmentVariable("DATABASE_URL")??builder.Configuration.GetConnectionString("Default"); if(!string.IsNullOrWhiteSpace(cs)&&cs.StartsWith("postgresql://")){var u=new Uri(cs);var q=System.Web.HttpUtility.ParseQueryString(u.Query);cs=$"Host={u.Host};Port={u.Port};Database={u.AbsolutePath.Trim('/')};Username={u.UserInfo.Split(':')[0]};Password={u.UserInfo.Split(':')[1]};SSL Mode=Require;Trust Server Certificate=true";} builder.Services.AddDbContext<AppDbContext>(o=>o.UseNpgsql(cs??"Host=localhost;Database=coffeecontrol;Username=postgres;Password=postgres")); builder.Services.AddSingleton<TelegramAuth>(); builder.Services.AddControllers(); builder.Services.AddEndpointsApiExplorer(); builder.Services.AddCors(o=>o.AddDefaultPolicy(p=>p.AllowAnyHeader().AllowAnyMethod().AllowAnyOrigin()));
var app=builder.Build(); app.UseForwardedHeaders(); app.UseDefaultFiles(); app.UseStaticFiles(); app.UseCors(); using(var scope=app.Services.CreateScope()){var db=scope.ServiceProvider.GetRequiredService<AppDbContext>(); await db.Database.MigrateAsync(); await DbSeeder.SeedAsync(db,default);} app.MapGet("/health",()=>Results.Ok(new{status="ok",utc=DateTime.UtcNow}));
var botToken=builder.Configuration["TELEGRAM_BOT_TOKEN"]; var webAppUrl=builder.Configuration["TELEGRAM_WEBAPP_URL"]??builder.Configuration["APP_BASE_URL"]; var bot=string.IsNullOrWhiteSpace(botToken)?null:new TelegramBotClient(botToken);
if(bot is not null && !string.IsNullOrWhiteSpace(webAppUrl) && !app.Environment.IsDevelopment()) await bot.SetWebhook($"{webAppUrl.TrimEnd('/')}/telegram/webhook",secretToken:builder.Configuration["TELEGRAM_WEBHOOK_SECRET"]);
app.MapPost("/telegram/webhook",async(Update update)=>{if(bot is null||update.Message?.Text is null)return Results.Ok();var chat=update.Message.Chat.Id;var text=update.Message.Text.Trim();if(text.StartsWith("/start")||text.StartsWith("/app")){var markup=string.IsNullOrWhiteSpace(webAppUrl)?null:new InlineKeyboardMarkup(InlineKeyboardButton.WithWebApp("☕ Открыть кофейню",new WebAppInfo{Url=webAppUrl}));await bot.SendMessage(chat,"☕ Coffee Control\n\nКасса и смены вашей кофейни в одном приложении.",replyMarkup:markup);}else if(text.StartsWith("/help"))await bot.SendMessage(chat,"/start — открыть Coffee Control\n/app — открыть приложение\n/help — помощь");return Results.Ok();});
app.MapGet("/api/me",async(HttpRequest r,AppDbContext db,TelegramAuth auth,CancellationToken ct)=>{var u=await auth.AuthenticateAsync(r,db,ct);return u is null?Results.Unauthorized():Results.Ok(new{id=u.Id,u.TelegramId,u.FirstName,u.Role});});
app.MapGet("/api/products",async(AppDbContext db,CancellationToken ct)=>Results.Ok(await db.Products.Include(x=>x.Variants).Include(x=>x.Category).Where(x=>x.IsActive).OrderBy(x=>x.SortOrder).Select(x=>new{id=x.Id,name=x.Name,category=x.Category.Name,icon=x.Category.Icon,quick=x.IsQuickOrder,variants=x.Variants.Where(v=>v.IsActive).Select(v=>new{id=v.Id,name=v.Name,price=v.Price,volumeMl=v.VolumeMl})}).ToListAsync(ct)));
app.MapGet("/api/dashboard",async(HttpRequest r,AppDbContext db,TelegramAuth auth,CancellationToken ct)=>{var u=await auth.AuthenticateAsync(r,db,ct);if(u is null)return Results.Unauthorized();var s=await db.Shifts.Include(x=>x.Orders).ThenInclude(x=>x.Payments).Where(x=>x.UserId==u.Id&&x.BusinessDate==DateOnly.FromDateTime(DateTime.UtcNow.AddHours(3))).OrderByDescending(x=>x.OpenedAt).FirstOrDefaultAsync(ct);if(s is null)return Results.Ok(new{currentShift=(object?)null});var orders=s.Orders.Where(x=>x.Status==OrderStatus.Completed);return Results.Ok(new{currentShift=new{id=s.Id,s.OpenedAt,s.OpeningCash,s.Status},revenue=orders.Sum(x=>x.TotalAmount),ordersCount=orders.Count(),cash=orders.SelectMany(x=>x.Payments).Where(x=>x.PaymentMethod==PaymentMethod.Cash).Sum(x=>x.Amount),card=orders.SelectMany(x=>x.Payments).Where(x=>x.PaymentMethod==PaymentMethod.Card).Sum(x=>x.Amount),averageCheck=orders.Any()?orders.Average(x=>x.TotalAmount):0,recentOrders=orders.OrderByDescending(x=>x.CreatedAt).Take(10).Select(x=>new{x.Number,x.TotalAmount,x.CreatedAt,status=x.Status.ToString(),items=x.Items.Select(i=>i.ProductNameSnapshot+" × "+i.Quantity)})});});
app.MapPost("/api/shifts/open",async(HttpRequest r,AppDbContext db,TelegramAuth auth,OpenShiftDto dto,CancellationToken ct)=>{var u=await auth.AuthenticateAsync(r,db,ct);if(u is null)return Results.Unauthorized();if(await db.Shifts.AnyAsync(x=>x.UserId==u.Id&&x.Status==ShiftStatus.Open,ct))return Results.BadRequest(new{code="SHIFT_ALREADY_OPEN",message="Смена уже открыта."});var s=new Shift{UserId=u.Id,BusinessDate=DateOnly.FromDateTime(DateTime.UtcNow.AddHours(3)),OpeningCash=dto.OpeningCash,ExpectedClosingCash=dto.OpeningCash};db.Shifts.Add(s);await db.SaveChangesAsync(ct);return Results.Ok(s);});
app.MapPost("/api/shifts/{id:guid}/close",async(Guid id,HttpRequest r,AppDbContext db,TelegramAuth auth,CloseShiftDto dto,CancellationToken ct)=>{var u=await auth.AuthenticateAsync(r,db,ct);if(u is null)return Results.Unauthorized();var s=await db.Shifts.Include(x=>x.Orders).ThenInclude(x=>x.Payments).SingleOrDefaultAsync(x=>x.Id==id&&x.UserId==u.Id,ct);if(s is null)return Results.NotFound();if(dto.ActualCash<0)return Results.BadRequest(new{code="INVALID_CASH",message="Касса не может быть отрицательной."});var cash=s.Orders.Where(x=>x.Status==OrderStatus.Completed).SelectMany(x=>x.Payments).Where(x=>x.PaymentMethod==PaymentMethod.Cash).Sum(x=>x.Amount);s.ExpectedClosingCash=s.OpeningCash+cash;s.ActualClosingCash=dto.ActualCash;s.CashDifference=dto.ActualCash-s.ExpectedClosingCash;s.ClosedAt=DateTime.UtcNow;s.Status=ShiftStatus.Closed;s.Comment=dto.Comment;await db.SaveChangesAsync(ct);return Results.Ok(s);});
app.MapPost("/api/orders",async(HttpRequest r,AppDbContext db,TelegramAuth auth,CreateOrderDto dto,CancellationToken ct)=>{var u=await auth.AuthenticateAsync(r,db,ct);if(u is null)return Results.Unauthorized();var existing=await db.Orders.Include(x=>x.Items).SingleOrDefaultAsync(x=>x.RequestId==dto.RequestId,ct);if(existing is not null)return Results.Ok(existing);var s=await db.Shifts.SingleOrDefaultAsync(x=>x.UserId==u.Id&&x.Status==ShiftStatus.Open,ct);if(s is null)return Results.BadRequest(new{code="SHIFT_NOT_OPEN",message="Откройте смену перед созданием заказа."});var ids=dto.Items.Select(x=>x.VariantId).ToArray();var variants=await db.Variants.Include(x=>x.Product).Where(x=>ids.Contains(x.Id)).ToDictionaryAsync(x=>x.Id,ct);var order=new Order{ShiftId=s.Id,UserId=u.Id,RequestId=dto.RequestId,Number=(await db.Orders.MaxAsync(x=>(long?)x.Number,ct)??0)+1};foreach(var i in dto.Items){if(!variants.TryGetValue(i.VariantId,out var v))return Results.BadRequest(new{code="PRODUCT_NOT_FOUND",message="Товар не найден."});var unit=v.Price+i.ModifierAmount;order.Items.Add(new OrderItem{ProductId=v.ProductId,ProductVariantId=v.Id,ProductNameSnapshot=v.Product.Name,VariantNameSnapshot=v.Name,BasePrice=v.Price,Quantity=i.Quantity,UnitPrice=unit,TotalPrice=unit*i.Quantity});}order.TotalAmount=order.Items.Sum(x=>x.TotalPrice);if(dto.Payments.Sum(x=>x.Amount)!=order.TotalAmount)return Results.BadRequest(new{code="PAYMENT_MISMATCH",message="Сумма оплаты не совпадает с заказом."});order.Payments=dto.Payments.Select(x=>new Payment{PaymentMethod=x.Method,Amount=x.Amount}).ToList();db.Orders.Add(order);s.ExpectedClosingCash+=order.Payments.Where(x=>x.PaymentMethod==PaymentMethod.Cash).Sum(x=>x.Amount);await db.SaveChangesAsync(ct);return Results.Ok(order);});
app.MapGet("/api/orders",async(HttpRequest r,AppDbContext db,TelegramAuth auth,CancellationToken ct)=>{var u=await auth.AuthenticateAsync(r,db,ct);if(u is null)return Results.Unauthorized();return Results.Ok(await db.Orders.Include(x=>x.Items).Include(x=>x.Payments).Where(x=>x.UserId==u.Id).OrderByDescending(x=>x.CreatedAt).Take(100).Select(x=>new{x.Id,x.Number,x.TotalAmount,x.CreatedAt,status=x.Status.ToString(),payments=x.Payments.Select(p=>p.PaymentMethod.ToString()),items=x.Items.Select(i=>new{name=i.ProductNameSnapshot,quantity=i.Quantity})}).ToListAsync(ct));});
app.MapFallbackToFile("index.html"); app.Run();
public record OpenShiftDto(decimal OpeningCash); public record CloseShiftDto(decimal ActualCash,string? Comment); public record CreateItemDto(Guid VariantId,int Quantity,decimal ModifierAmount=0); public record CreatePaymentDto(PaymentMethod Method,decimal Amount); public record CreateOrderDto(string RequestId,List<CreateItemDto> Items,List<CreatePaymentDto> Payments);
public partial class Program { }
